"""Freeze only the independently accepted DIC sparse operation; write no board."""
from pathlib import Path
import hashlib,json,re
H=Path(__file__).resolve().parent
def sha(b):return hashlib.sha256(b).hexdigest()
def load(p):return json.loads(p.read_bytes())
def main():
 constructor=H/'DIC-In2-actual-paired-CMD-construction-r198.json';raw=constructor.read_bytes();assert sha(raw)=='d26522a045ba719d951966d69a41860a68ca3cd064a35b4d767aa109956bed9d';recipe=json.loads(raw);sel=recipe['selected']
 independent=H/'DIC-In2-supported-independent-r204.json';audit=load(independent);assert audit['verdict']=='DIC_IN2_SUPPORTED_OWN_INDEPENDENT_HOST_LATEST_R214_MUTUAL_PASS_COMBINED_NATIVE_OPEN';assert audit['R198_receipt_sha256']==sha(raw)
 source=H.parent/'sbc-native-contract-r1/sbc-owned-native-contract.kicad_pcb';src=source.read_bytes();assert sha(src)==recipe['source_parent_sha256']==audit['source_parent_sha256']=='eedf63f2c24346a885cebcabbd7546576663d5cbb29bc8dbd48401921201240a'
 deleted={uid:ch.encode() for uid,ch in sel['exact_deleted_chunks'].items()};new={uid:ch.encode() for uid,ch in sel['exact_new_chunks'].items()};assert len(deleted)==4 and len(new)==25;assert set(deleted)==set(recipe['removed_exact_source_UUIDs']);assert sha(b''.join(deleted[uid] for uid in sorted(deleted)))==audit['exact4_deleted_chunks_sha256'];assert sha(b''.join(new[uid] for uid in sorted(new)))==audit['all_exact_added_chunks_sha256']
 out=H/'DIC-native-owned-ledger-r206';assert not out.exists();out.mkdir();rows=[];newfiles=[];removefiles={}
 for action,items in(('remove',deleted),('add',new)):
  for uid,ch in sorted(items.items()):
   kind=re.match(rb'\s*\(([^\s()]+)',ch).group(1).decode();assert kind in('segment','via') and ('(uuid "'+uid+'")').encode() in ch
   if action=='remove':assert kind=='segment' and src.count(ch)==1
   else:assert uid.encode() not in src and src.count(ch)==0
   file=out/f'{action}-{uid}.{kind}-chunk';file.write_bytes(ch);entry={'action':action,'uuid':uid,'kind':kind,'exact_chunk_path':str(file),'exact_chunk_sha256':sha(ch),'native_item_provenance':'Exact original eedf source' if action=='remove' else'Exact R198 serialized chunk independently rebuilt by R204'};rows.append(entry)
   if action=='remove':removefiles[uid]=entry
   else:newfiles.append({'UUID':uid,'kind':kind,'chunk_file':str(file),'chunk_sha256':sha(ch)})
 assert sum(q['kind']=='segment' for q in newfiles)==20 and sum(q['kind']=='via' for q in newfiles)==5
 report={'schema':'DIC-exact-four-delete-twenty-five-add-native-owned-ledger-r206','verdict':'EXACT_SPARSE_OPERATION_INDEPENDENT_R204_HOST_PASS_COMBINED_NATIVE_OPEN','source_parent':str(source),'source_parent_sha256':sha(src),'frozen_constructor_file':str(constructor),'frozen_constructor_sha256':sha(raw),'frozen_constructor_model_file':sel['model_file'],'frozen_constructor_model_sha256':sel['model_sha256'],'independent_audit_file':str(independent),'independent_audit_sha256':sha(independent.read_bytes()),'independent_physical_checkpoint_file':audit['physical_checkpoint_file'],'independent_physical_checkpoint_sha256':audit['physical_checkpoint_sha256'],'rows':rows,'exact_deleted_current_chunks':removefiles,'exact_new_chunk_files':newfiles,'counts':{'owned_original_segments_removed':4,'new_segments':20,'new_ordinary_all6_vias':5,'new_zones':0,'FP_replacements':0,'pad_or_net_retags':0,'rule_or_project_changes':0},'signal_layers':['F.Cu','In2.Cu','F.Cu'],'all_new_track_width_mm':.2,'all_new_via_diameter_drill_mm':[.5,.2],'CMD_original_barrel_UUID':'1f815e33-e973-46e2-833e-96fee8d37fcf','CMD_original_barrel_pose_size_annuli_exact':True,'CMD_new_tracks_preserve_locked_yes':True,'native_stackup_and_signal_leg_binding':audit['native_stackup_and_signal_leg_binding'],'source_endpoint_contract':{'normalized_net':'/motherboard_io_control/DIC_IOL1_CS_BUFFER','native_r06_labels':['R13013.1#0','U13003.3#0'],'actual_pad_UUIDs':['c9bab2fa-e6cb-45f7-b879-a934865b0e12','73d7d605-feb4-47ae-b36a-40896fba4ee9']},'actual_source_paired_returns':audit['actual_source_paired_returns'],'source_supported_own_aperture_ledger':audit['source_supported_actual_own_apertures'],'exact_latest_mutual_binding':audit['latest_actual_R214_IO3_R201_C1022_R222_exact_mutual']['bound_inputs_sha256'] if 'bound_inputs_sha256' in audit['latest_actual_R214_IO3_R201_C1022_R222_exact_mutual'] else audit['latest_actual_R214_IO3_R201_C1022_R222_exact_mutual'],'original_source_Cu_FP_pose_zone_design_rule_project_unchanged_except_exact_four_segments':True,'all_current_r06_r07_signal_pad_relationships_and_prior_source_layer_keys_host_retained':True,'every_affected_surviving_layer_key_and_direct_same_zone_contact_host_retained':True,'all_new_and_retained_full_body_reference_host_retained':True,'combined_latest_all_power_source_current_contact_native_r06_r07_DRC_SI':'OPEN; apply only these exact4 deletes/25 additions to integrator current head, never overlay the saved local model','native_all6_actual_via_flashes_and_exact_raw_net_IU_source_gate':'OPEN; prospective all6 host geometry is not native flash qualification','matching_fresh_before_after_fill_reference_and_contact_gate':'OPEN','native_jobs':0,'board_written':False,'live_or_source_or_project_written':False,'adopted':False,'emitter_script':str(Path(__file__).resolve()),'emitter_script_sha256':sha(Path(__file__).read_bytes())}
 receipt=out/'receipt.json';receipt.write_text(json.dumps(report,indent=1,allow_nan=False)+'\n');print(json.dumps({'receipt':str(receipt),'sha256':sha(receipt.read_bytes()),'counts':report['counts']}))
